const rows=$('THEMES — Récents').all().map(r=>r.json).filter(x=>x.Titre);
const base=$now.setZone('Africa/Lagos');
const du=((8-base.weekday)%7)||7;
const monday=base.plus({days:du}).startOf('day');
const sunday=monday.plus({days:7});
const semaine=monday.toFormat('dd LLL');
let targetCount=0;
for(const x of rows){const d=x.Date_Publication_Prevue;if(!d)continue;const dt=DateTime.fromISO(d);if(dt.isValid&&dt>=monday&&dt<sunday)targetCount++;}
const skip=targetCount>=5;
const recents=rows.map(x=>({t:x.Titre,d:x.Date_Publication_Prevue||''})).sort((a,b)=>(b.d>a.d?1:-1)).slice(0,25).map(x=>x.t);
const prompt=`Tu es **CMO Aïcha**, directrice marketing de Max-Morrys (agence personal branding + LMS, tagline « Maîtrise le digital, accélère ta croissance »). Cible : entrepreneurs 25-45 ans d'Afrique francophone + diaspora.
Propose **4 thématiques éditoriales** distinctes, actuelles et déclinables, pour la semaine du ${semaine}. Elles mêlent personal branding, marketing digital et IA. Chaque thème doit pouvoir se décliner en ~10 posts (LinkedIn/IG/FB en primaire, un peu de TikTok/X).
Inclus au moins 1 thème qui surfe une **tendance chaude** du moment (ex : GEO/AEO et être cité par ChatGPT/Gemini, agents IA pour solopreneurs, saturation du contenu IA & prime à l'authenticité, faceless/UGC IA, founder-led content, IA souveraine en Afrique...).
Évite de répéter ces sujets déjà traités récemment : ${recents.join(' | ')}.
Réponds STRICTEMENT en JSON, sans texte autour : {"themes":[{"titre":"court et accrocheur","angle":"1 phrase sur l'angle éditorial","pourquoi":"pourquoi ce thème maintenant, 1 phrase"}]} — exactement 4 objets.`;
return [{json:{prompt,skip,targetCount,semaine}}];

const cfg={};for(const r of $('THEMES — Lire Config').all())if(r.json.Cle)cfg[r.json.Cle]=r.json.Valeur;
let g=$input.first().json;
// Extraction robuste : gere l'objet simplifie {themes:[...]} ET l'enveloppe Gemini brute {candidates:[{content:{parts:[{text}]}}]}
function pickText(x){
  if(x==null)return null;
  if(typeof x==='string')return x;
  if(Array.isArray(x)){for(const e of x){const t=pickText(e);if(t)return t;}return null;}
  if(typeof x==='object'){
    if(x.candidates)return pickText(x.candidates);
    if(x.content)return pickText(x.content);
    if(x.parts)return pickText(x.parts);
    if(typeof x.text==='string')return x.text;
    if(x.output)return pickText(x.output);
    if(x.message)return pickText(x.message);
  }
  return null;
}
let themes=[];
if(g&&Array.isArray(g.themes))themes=g.themes;
else if(g&&Array.isArray(g.Themes))themes=g.Themes;
else{
  let txt=pickText(g);
  if(typeof txt==='string'){
    txt=txt.trim().replace(/^```(json)?/i,'').replace(/```$/,'').trim();
    try{const o=JSON.parse(txt);themes=o.themes||o.Themes||(Array.isArray(o)?o:[]);}catch(e){}
  }
}
if(!Array.isArray(themes))themes=[];
themes=themes.filter(t=>t&&t.titre).slice(0,4);
// Plus de fallback silencieux a 1 theme : si <2 themes reels, on echoue -> alerte WF-ERR
if(themes.length<2)throw new Error('THEMES: extraction Gemini a echoue ('+themes.length+' theme) — sortie='+JSON.stringify(g).slice(0,300));
const lines=themes.map((t,i)=>`<b>${i+1}. ${t.titre}</b>\n${t.angle||''}\n<i>${t.pourquoi||''}</i>`).join('\n\n');
const text=`🗓️ <b>CMO Aïcha — thèmes proposés (semaine prochaine)</b>\n\n${lines}\n\n👉 Choisis-en un ci-dessous : je le décline en 10 posts prêts à valider.`;
const kb={inline_keyboard:themes.map((t,i)=>[{text:`${i+1}. ${String(t.titre).slice(0,32)}`,callback_data:`pick:theme:${i}`}])};
const tgBody={chat_id:cfg.TELEGRAM_CHAT_ID,text,parse_mode:'HTML',reply_markup:kb};
return [{json:{token:cfg.TELEGRAM_BOT_TOKEN,themesJson:JSON.stringify(themes),tgBody}}];

